// Parameter sweep of f(x; c) = x^3 - 2x - c over c = 1, 3, 5, 7.
// Prints one human line per scenario, one line starting with "RESULTS " carrying the structured document
// (schema ostrin.results/v1), and the comparative SVG figure. Exit status 1 when a check fails.
import std.numeric
import model
import sweep
import graphics

fn main() -> Int {
    r1 = sweep.scenario(1.0, model.g1)
    r3 = sweep.scenario(3.0, model.g3)
    r5 = sweep.scenario(5.0, model.g5)
    r7 = sweep.scenario(7.0, model.g7)
    mut failures = sweep.failure_count(r1) + sweep.failure_count(r3) + sweep.failure_count(r5) + sweep.failure_count(r7)
    print(sweep.report_line(r1))
    print(sweep.report_line(r3))
    print(sweep.report_line(r5))
    print(sweep.report_line(r7))
    if sweep.failure_count(r1) == 1 { print(sweep.fail_line(r1)) }
    if sweep.failure_count(r3) == 1 { print(sweep.fail_line(r3)) }
    if sweep.failure_count(r5) == 1 { print(sweep.fail_line(r5)) }
    if sweep.failure_count(r7) == 1 { print(sweep.fail_line(r7)) }
    // A bracket without a sign change must report the method's error; an Ok here is a failed check.
    match numeric.brent(model.g1, 0.0, 1.0) {
        Ok(root) => {
            print("FAIL unexpected root in [0, 1]: " + root.to_string())
            failures = failures + 1
        },
        Err(message) => print("expected error for [0, 1]: " + message),
    }
    document = "{\"schema\":\"ostrin.results/v1\",\"experiment\":\"cubic-parameter-sweep\",\"family\":\"x^3 - 2x - c\",\"bracket\":[1.0,3.0],\"rows\":[" + sweep.row_json(r1) + "," + sweep.row_json(r3) + "," + sweep.row_json(r5) + "," + sweep.row_json(r7) + "]}"
    print("RESULTS " + document)
    print(graphics.figure(1.0, 3.0, 5.0, 7.0, r1.root, r3.root, r5.root, r7.root))
    if failures == 0 {
        print("all checks passed")
        0
    } else {
        print("checks failed: " + failures.to_string())
        1
    }
}

files.model.ostrin:
// The family f(x; c) = x^3 - 2x - c. One definition for every scenario: the parameter is an argument.
// Ostrin has no closures, so std.numeric.brent (which takes a one-argument function) receives the named
// wrappers g1, g3, g5, g7 below, each fixing c for one scenario.
pub fn f(x: Float, c: Float) -> Float {
    x * x * x - 2.0 * x - c
}

// Analytic derivative in x; it does not depend on c.
pub fn df(x: Float) -> Float {
    3.0 * x * x - 2.0
}

// Vectorised over the samples of x for one parameter value c.
pub fn samples(xs: Array<Float>, c: Float) -> Array<Float> {
    xs * xs * xs - xs * 2.0 - c
}

pub fn g1(x: Float) -> Float {
    f(x, 1.0)
}

pub fn g3(x: Float) -> Float {
    f(x, 3.0)
}

pub fn g5(x: Float) -> Float {
    f(x, 5.0)
}

pub fn g7(x: Float) -> Float {
    f(x, 7.0)
}

files.sweep.ostrin:
// One scenario per parameter value: the root by Brent's method on [1, 3], its residual, the analytic and the
// finite-difference derivative, and the convergence status. Every check is strict: a comparison passes only
// when it is true, so NaN and infinities fail.
import std.numeric
import model

// Result of one scenario. `passed` is true only when the root converged and every check holds.
pub record Row {
    c: Float
    status: String
    root: Float
    residual: Float
    residual_bound: Float
    analytic: Float
    numeric: Float
    passed: Bool
    message: String
}

// |a - b| <= tol; NaN and infinities make the comparison false.
pub fn close_to(a: Float, b: Float, tol: Float) -> Bool {
    abs(a - b) <= tol
}

// The scenario for one parameter value c, using the wrapper g that fixes it.
pub fn scenario(c: Float, g: fn(Float) -> Float) -> Row {
    match numeric.brent(g, 1.0, 3.0) {
        Ok(root) => {
            residual = model.f(root, c)
            analytic = model.df(root)
            numerical = numeric.derivative(g, root)
            bound = 10.0 * abs(analytic) * 1e-12
            residual_ok = close_to(residual, 0.0, bound)
            derivative_ok = close_to(numerical, analytic, 1e-5)
            Row { c: c, status: "converged", root: root, residual: residual, residual_bound: bound, analytic: analytic, numeric: numerical, passed: residual_ok and derivative_ok, message: "" }
        },
        Err(message) => Row { c: c, status: "failed", root: 0.0, residual: 0.0, residual_bound: 0.0, analytic: 0.0, numeric: 0.0, passed: false, message: message },
    }
}

// One row as a JSON object. Numbers use Ostrin's shortest round-trip text.
pub fn row_json(r: Row) -> String {
    passed = if r.passed { "true" } else { "false" }
    "{\"c\":" + r.c.to_string() + ",\"status\":\"" + r.status + "\",\"root\":" + r.root.to_string() + ",\"residual\":" + r.residual.to_string() + ",\"residual_bound\":" + r.residual_bound.to_string() + ",\"analytic_derivative\":" + r.analytic.to_string() + ",\"numeric_derivative\":" + r.numeric.to_string() + ",\"passed\":" + passed + ",\"message\":\"" + r.message + "\"}"
}

// One human line for a scenario.
pub fn report_line(r: Row) -> String {
    "c = " + r.c.to_string() + ": status " + r.status + ", root " + r.root.to_string() + ", residual " + abs(r.residual).to_string() + ", passed " + row_passed_text(r)
}

pub fn row_passed_text(r: Row) -> String {
    if r.passed { "true" } else { "false" }
}

// 1 when the scenario failed a check, 0 otherwise.
pub fn failure_count(r: Row) -> Int {
    if r.passed { 0 } else { 1 }
}

// The FAIL line for a failed scenario.
pub fn fail_line(r: Row) -> String {
    "FAIL c = " + r.c.to_string() + " " + r.status + " " + r.message
}
